{"lesson": "The receipts are consistent with a main-connection changes() channel and INSERT OR IGNORE put handling: the first receipt's rollback resets changes() to 0, the second receipt's delete leaves changes() at 1, and the fourth receipt's ignored second put leaves changes() at 0. The committed state is ordinary SQLite state, so the first receipt leaves one row with value 1, the second leaves one row with value 4, the third leaves zero rows, and the fourth leaves one row with value 77. The predictor simulates the disclosed family and returns a value only when all consistent members agree.", "scope": "Predicts channel, committed_count, and committed_sum for action sequences over the disclosed SQLite family, using the calibration receipts to identify the put conflict handling, instrumentation, and channel. Supports sequences with at most 32 actions, keys up to 40 characters, integer values 0..1000000, and transactions that do not nest.", "source": "def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, channel_mode, trigger):
        main = {}
        other = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        log = []
        in_tx = False
        tx_conn = None
        tx_snapshot = None

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            if op == "begin":
                in_tx = True
                tx_conn = conn
                if conn == "main":
                    tx_snapshot = dict(main)
                else:
                    tx_snapshot = dict(other)
            elif op == "commit":
                in_tx = False
                tx_conn = None
                tx_snapshot = None
            elif op == "rollback":
                if tx_conn == "main":
                    main.clear()
                    main.update(tx_snapshot)
                else:
                    other.clear()
                    other.update(tx_snapshot)
                in_tx = False
                tx_conn = None
                tx_snapshot = None
                if conn == "main":
                    main_changes = 0
            elif op == "put":
                key = action.get("key")
                value = action.get("value")
                if conn == "main":
                    if put_mode == "ignore":
                        if key not in main:
                            main[key] = value
                            main_changes = 1
                            main_total += 1
                            if trigger:
                                log.append((key, value))
                        else:
                            main_changes = 0
                    elif put_mode == "replace":
                        main[key] = value
                        main_changes = 1
                        main_total += 1
                        if trigger:
                            log.append((key, value))
                    else:
                        main[key] = value
                        main_changes = 1
                        main_total += 1
                        if trigger:
                            log.append((key, value))
                else:
                    if put_mode == "ignore":
                        if key not in other:
                            other[key] = value
                            other_total += 1
                            if trigger:
                                log.append((key, value))
                    elif put_mode == "replace":
                        other[key] = value
                        other_total += 1
                        if trigger:
                            log.append((key, value))
                    else:
                        other[key] = value
                        other_total += 1
                        if trigger:
                            log.append((key, value))
            elif op == "update":
                key = action.get("key")
                value = action.get("value")
                if conn == "main":
                    if key in main:
                        main[key] = value
                        main_changes = 1
                        main_total += 1
                    else:
                        main_changes = 0
                else:
                    if key in other:
                        other[key] = value
                        other_total += 1
            elif op == "delete":
                key = action.get("key")
                if conn == "main":
                    if key in main:
                        del main[key]
                        main_changes = 1
                        main_total += 1
                    else:
                        main_changes = 0
                else:
                    if key in other:
                        del other[key]
                        other_total += 1

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total_main":
            channel = main_total
        else:
            channel = main_total + other_total
        committed = dict(main)
        committed.update(other)
        return channel, len(committed), sum(committed.values())

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for channel_mode in ("changes", "total_main", "total_both"):
            for trigger in (False, True):
                ok = True
                for receipt in history:
                    actions = receipt.get("actions", [])
                    observed = receipt.get("observed", {})
                    ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
                    if ch != observed.get("channel") or cnt != observed.get("committed_count") or sm != observed.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, channel_mode, trigger))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, channel_mode, trigger in candidates:
        ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cnt)
        elif goal == "committed_sum":
            values.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}
"}
